[InitializeOnLoad]
public static class AdventureV2Builder {
 const string Source="Assets/Art/V2/Sprites/", Out="Assets/Animations/V2/";
 static List<string> manifest=new List<string>();
 static AdventureV2Builder(){EditorApplication.update+=Tick;}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/V2/build.request"))return;File.Delete("Temp/V2/build.request");try{Build();File.WriteAllText("Temp/V2/built.txt",DateTime.Now.ToString("s"));}catch(Exception e){File.WriteAllText("Temp/V2/error.txt",e.ToString());Debug.LogException(e);}}
 [MenuItem("Amazonia/V2/Integrar recursos y secuencias")]
 public static void Build(){Directory.CreateDirectory(Out);AssetDatabase.Refresh();manifest.Clear();
  foreach(var path in Directory.GetFiles(Source,"*.png",SearchOption.AllDirectories)){var imp=(TextureImporter)AssetImporter.GetAtPath(path.Replace('\\','/'));imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=4096;imp.alphaIsTransparency=true;imp.SaveAndReimport();}
  foreach(bool water in new[]{false,true}){string pn=water?"CapybaraAcuatico":"CapybaraTerrestre",bn=water?"CaimanAcuatico":"CaimanTerrestre";
   var pc=AssetDatabase.LoadAssetAtPath<AnimatorController>("Assets/Animations/Amazonia/"+pn+"/Controller.controller");var bc=Controller(bn);
   PlayerAnimations(pc,water);BossAnimations(bc,water);
   string pp="Assets/Prefabs/Amazonia/"+(water?"CapibaraAcuatico":"CapibaraTerrestre")+".prefab",bp="Assets/Prefabs/Amazonia/"+bn+".prefab";
   var p=PrefabUtility.LoadPrefabContents(pp);if(!p.GetComponent<PlasmaMagazine>())p.AddComponent<PlasmaMagazine>();var em=p.GetComponent<AdventureEmotes>()??p.AddComponent<AdventureEmotes>();em.wazaaaa=Load<AudioClip>("Sonidos/emote_wazaaaa.wav");em.uiia=Load<AudioClip>("Sonidos/emote_uiia.wav");em.sixSeven=Load<AudioClip>("Sonidos/emote_six_seven.wav");PrefabUtility.SaveAsPrefabAsset(p,pp);PrefabUtility.UnloadPrefabContents(p);
   var b=PrefabUtility.LoadPrefabContents(bp);b.GetComponent<Animator>().runtimeAnimatorController=bc;var v=b.GetComponent<AdventureVisual>();v.facesLeft=false;v.sprite.sprite=First(bc);var c=b.GetComponent<CapsuleCollider2D>();c.direction=water?CapsuleDirection2D.Horizontal:CapsuleDirection2D.Vertical;c.size=water?new Vector2(2.5f,1):new Vector2(1.3f,1.9f);c.offset=water?new Vector2(.2f,0):new Vector2(.15f,0);PrefabUtility.SaveAsPrefabAsset(b,bp);PrefabUtility.UnloadPrefabContents(b);
   EditorSceneManager.OpenScene("Assets/Scenes/Amazonia"+(water?"Acuatica":"Terrestre")+".unity");var flow=UnityEngine.Object.FindAnyObjectByType<AdventureFlow>();var director=flow.GetComponent<AdventureDirector>()??flow.gameObject.AddComponent<AdventureDirector>();if(!flow.GetComponent<AdventureAudio>())flow.gameObject.AddComponent<AdventureAudio>();director.escapeClip=Load<VideoClip>("Videos/Caiman_Cinematica.mp4");director.capyPortrait=Sprite("PortraitCapy","Retratos_Dialogos.png",new Rect(20,40,205,195),100);director.caimanPortrait=Sprite("PortraitCaiman","Retratos_Dialogos.png",new Rect(10,265,185,193),100);director.capsuleFull=Sprite("CapsuleFull","Recarga_Arma.png",new Rect(970,130,140,185),100);director.capsuleEmpty=Sprite("CapsuleEmpty","Recarga_Arma.png",new Rect(1210,135,90,170),100);
   flow.controls.text+="    T  EMOTES";
   // Las instancias mantienen posición, referencias y geometría física de V1.
   flow.boss.visual.facesLeft=false;flow.boss.visual.animator.runtimeAnimatorController=bc;flow.boss.visual.sprite.sprite=First(bc);flow.boss.visual.sprite.flipX=true;
   if(!water)flow.boss.transform.position=new Vector3(38,1.1f,0);
   var background=GameObject.Find("Panorama original");if(background)background.GetComponent<SpriteRenderer>().sprite=Load<UnityEngine.Sprite>("Fondos/Fondo"+(water?"Acuatico":"Terrestre")+".png");
   Environment(water);EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
  }
  File.WriteAllLines("Documentation/V2/Recortes.tsv",new[]{"Nombre\tFuente\tx\tySuperior\tancho\talto\tPPU\tpivote"}.Concat(manifest));AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/AmazoniaTerrestre.unity");Debug.Log("V2 BUILD COMPLETE");
 }
 static T Load<T>(string p)where T:UnityEngine.Object=>AssetDatabase.LoadAssetAtPath<T>(Source+p);
 static AnimatorController Controller(string name){string path=Out+name+".controller";var c=AssetDatabase.LoadAssetAtPath<AnimatorController>(path)??AnimatorController.CreateAnimatorControllerAtPath(path);if(c.layers.Length==0)c.AddLayer("Base Layer");return c;}
 static Sprite First(AnimatorController c){var clip=(AnimationClip)c.layers[0].stateMachine.states.First(x=>x.state.name=="Idle").state.motion;return (Sprite)AnimationUtility.GetObjectReferenceCurve(clip,AnimationUtility.GetObjectReferenceCurveBindings(clip)[0])[0].value;}
 static Sprite Sprite(string name,string source,Rect top,float ppu,Vector2? pivot=null){string path=Out+name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(existing)return existing;var tex=Load<Texture2D>(source);if(!tex)throw new Exception(source);var sp=UnityEngine.Sprite.Create(tex,new Rect(top.x,tex.height-top.y-top.height,top.width,top.height),pivot??Vector2.one*.5f,ppu,0,SpriteMeshType.FullRect);sp.name=name;AssetDatabase.CreateAsset(sp,path);manifest.Add($"{name}\t{source}\t{top.x}\t{top.y}\t{top.width}\t{top.height}\t{ppu}\t{pivot}");return sp;}
 static void Row(AnimatorController c,string state,string source,int y,int h,int[] xs,float ppu,bool loop=true,float fps=8,float px=.5f){string name=(c.name=="Controller"?new DirectoryInfo(Path.GetDirectoryName(AssetDatabase.GetAssetPath(c))).Name:c.name)+"_"+state,path=Out+name+".anim";var oldClip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(oldClip){Attach(c,state,oldClip);return;}var keys=new ObjectReferenceKeyframe[xs.Length];for(int i=0;i<xs.Length-1;i++){var sp=Sprite(name+i,source,new Rect(xs[i]+2,y,xs[i+1]-xs[i]-4,h),ppu,new Vector2(px,.5f));keys[i]=new ObjectReferenceKeyframe{time=i/fps,value=sp};}keys[keys.Length-1]=new ObjectReferenceKeyframe{time=(keys.Length-1)/fps,value=keys[loop?0:keys.Length-2].value};var clip=new AnimationClip{name=state,frameRate=fps};AnimationUtility.SetObjectReferenceCurve(clip,new EditorCurveBinding{path="Visual",type=typeof(SpriteRenderer),propertyName="m_Sprite"},keys);var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=loop;AnimationUtility.SetAnimationClipSettings(clip,settings);AssetDatabase.CreateAsset(clip,path);Attach(c,state,clip);}
 static void Attach(AnimatorController c,string state,AnimationClip clip){var machine=c.layers[0].stateMachine;var found=machine.states.FirstOrDefault(s=>s.state.name==state).state;var node=found?found:machine.AddState(state);node.motion=clip;if(state=="Idle")machine.defaultState=node;EditorUtility.SetDirty(c);AssetDatabase.SaveAssets();}
 static void PlayerAnimations(AnimatorController c,bool water){string t="Capybara/Terrestre/";Row(c,"Wazaaaa",t+"Emote_Wazaaaa.png",240,265,new[]{0,290,580,870,1150,1448},165,true,7);Row(c,"Uiia",t+"Emote_Uiia.png",290,205,new[]{0,240,480,720,960,1200,1448},132,true,10);Row(c,"SixSeven",t+"Emote_SixSeven.png",110,280,new[]{0,330,660,990,1320,1650,1983},180,true,7);Row(c,"DivePrepare",t+"Capybara_Sumerge.png",150,180,new[]{0,210,420,630,835,1045,1255,1465,1672},110,false,10);Row(c,"Dive",t+"Capybara_Sumerge.png",410,235,new[]{0,210,420,630,835,1045,1255,1465,1672},120,false,10);Row(c,"Reload",t+"Recarga_Y_Acabado_Plasma.png",380,170,new[]{0,245,485,730,975,1215,1448},110,true,5);Row(c,"Celebrate","Capybara/Acuatico/Capybara_Celebracion_Victoria_Terrestre_Acuatico.png",water?685:285,water?255:200,new[]{545,725,910,1090},water?160:125,true,6);}
 static void BossAnimations(AnimatorController c,bool water){string t="Caiman/"+(water?"Acuatico/":"Terrestre/");if(!water){Row(c,"Idle",t+"Caiman_Movimientos.png",10,205,new[]{0,245,450,660,865,1075,1275,1448},105,true,7,.65f);Row(c,"Run",t+"Caiman_Movimientos.png",500,180,new[]{0,210,400,590,785,990,1190,1448},95,true,9,.65f);Row(c,"Telegraph",t+"Caiman_Movimientos.png",245,230,new[]{0,245,450,660},110,false,4,.65f);Row(c,"Claw",t+"Caiman_Ataque_Cerca.png",65,232,new[]{0,250,470,665},110,false,7,.65f);Row(c,"Push",t+"Caiman_Ataque_Cerca.png",632,182,new[]{0,280,560,865},105,false,7,.6f);Row(c,"RockPrepare",t+"Caiman_Ataque_Distancia.png",195,182,new[]{0,245,470,670},100,false,5,.65f);Row(c,"Rock",t+"Caiman_Ataque_Distancia.png",390,189,new[]{0,260,530,845},105,false,6,.65f);Row(c,"Recovery",t+"Caiman_Movimientos.png",895,165,new[]{0,245,480},95,true,5,.65f);Row(c,"Hurt",t+"Caiman_Derrotado_Escape.png",10,174,new[]{0,220,435,650},100,false,8,.65f);Row(c,"Death",t+"Caiman_Derrotado_Escape.png",200,190,new[]{0,250,500},105,false,5,.65f);Row(c,"Escape",t+"Caiman_Derrotado_Escape.png",775,135,new[]{0,250,540,820,1100,1448},95,true,11,.65f);Row(c,"Appear",t+"Caiman_Aparicion.png",70,265,new[]{0,235,485,725,975,1190,1448},125,false,4,.65f);
 }else{string move=t+"Caiman_Acuatico_Movimiento_v2.png";int[] xs={0,285,565,840,1110,1380,1645,1900,2172};foreach(string state in new[]{"Idle","Swim","Recovery","Enraged","Hurt","Death"})Row(c,state,move,280,150,xs,100,state!="Death"&&state!="Hurt",state=="Death"?3:8,.6f);Row(c,"Telegraph",t+"Caiman_Acuatico_Movimiento_Preparar_Ataque_Rapido.png",285,182,new[]{0,245,500,725,960,1205,1440,1690,1940,2172},100,false,10,.6f);Row(c,"Charge",t+"Caiman_Movimiento_Ataque_Rapido_v1.png",280,149,new[]{0,315,630,945,1250,1570,1880,2172},110,true,12,.65f);Row(c,"ChargeAlt",t+"Caiman_Movimiento_Ataque_Rapido_v2.png",295,157,new[]{0,270,535,805,1070,1360,1645,1900,2172},105,true,12,.65f);Row(c,"Up",t+"Caiman_Acuatico_Movimiento_Diagonal_Superior.png",170,380,new[]{0,390,750,1110,1470,1830,2172},135,true,8,.6f);Row(c,"Down",t+"Caiman_Acuatico_Movimiento_Diagonal_Inferior.png",180,375,new[]{0,380,730,1090,1460,1820,2172},135,true,8,.6f);Row(c,"Appear",t+"Caiman_Acuatico_Aparicion.png",10,207,new[]{0,230,450,710,1040,1448},120,false,4,.6f);}}
 static void Environment(bool water){var old=GameObject.Find("Decoración V2");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Decoración V2");string path="Parallax/"+(water?"Acuatico/":"Terrestre/");
  Layer(root.transform,"Profundidad",water?"Parallax/Terrestre/Parallax_Fondo_Acuatico_Estructuras.png":path+"Parallax_Fondo_Bosque_v2.png",new Vector2(33,water?9:9),new Vector2(72,24),"Background",-19,.035f,new Color(.7f,.85f,.8f,.3f));
  Layer(root.transform,"Primer plano",path+(water?"Parallax_Raices_Bajo_Agua.png":"Parallax_Arboles_Lianas.png"),new Vector2(33,water?10:8),new Vector2(70,23),"EnvironmentFront",2,-.025f,new Color(1,1,1,.55f));
  if(water)Layer(root.transform,"Algas",path+"Parallax_Algas_v2.png",new Vector2(33,1),new Vector2(70,8),"EnvironmentBack",1,.015f,Color.white);
  var rock=water?Sprite("RockWater",path+"Parallax_Componentes_Acuaticopng.png",new Rect(1360,218,195,65),100):null;
  if(water)foreach(var poly in UnityEngine.Object.FindObjectsByType<PolygonCollider2D>()){foreach(var sr in poly.GetComponentsInChildren<SpriteRenderer>()){sr.enabled=false;}var r=new GameObject("Roca V2",typeof(SpriteRenderer)).GetComponent<SpriteRenderer>();r.transform.SetParent(poly.transform,false);r.sprite=rock;r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Generated/UnderwaterUnlit.mat");r.sortingLayerName="EnvironmentBack";r.transform.localScale=new Vector3(poly.bounds.size.x/rock.bounds.size.x,poly.bounds.size.y/rock.bounds.size.y,1);}
 }
 static void Layer(Transform parent,string name,string source,Vector2 pos,Vector2 size,string layer,int order,float factor,Color color){var r=new GameObject(name,typeof(SpriteRenderer)).GetComponent<SpriteRenderer>();r.transform.SetParent(parent,false);r.transform.position=pos;r.sprite=Load<Sprite>(source);r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Generated/UnderwaterUnlit.mat");r.color=color;r.sortingLayerName=layer;r.sortingOrder=order;r.transform.localScale=new Vector3(size.x/r.sprite.bounds.size.x,size.y/r.sprite.bounds.size.y,1);r.gameObject.AddComponent<AdventureParallax>().factor=factor;}
}


